{"code": "import pandas as pd
df = pd.read_excel('SoBanHang_2026.xlsx', sheet_name='Thang 03 2026')
df = df[['Hàng','so_luong','Unit','Trị giá','Status','Giá lẻ','Giờ','Mã hóa đơn','Ngày giao dịch','Khách']].copy()

def parse_date(v):
    if isinstance(v,(int,float)):
        # excel serial, epoch 1899-12-30
        return pd.Timestamp(pd.to_datetime(unit='D', origin=pd.Timestamp('1899-12-30'), args=[v]))
    s=str(v).strip()
    if s=='':
        return pd.NaT
    return pd.to_datetime(s, dayfirst=True, errors='coerce')

df['d']=df['Ngày giao dịch'].apply(parse_date)
print("null", df['d'].isna().sum())
print("min/max", df['d'].min(), df['d'].max())
print(df['d'].value_counts().head(15))
"}

